// script/site-truth/generate-languages.ts — restore the language dataset's generator.
//
// WHAT THIS REPLACES
// ------------------
// `website/src/data/brain-languages.ts` opened with
//   "GENERATED BY .tools/rebuild-languages.ts — edit that script's overrides"
// and `.tools/rebuild-languages.ts` did not exist in this repository. So a file
// the site renders as fact was hand-maintained in a repo whose rule is "generated
// or gated", and it drifted exactly as that predicts: the engine grew matlab and
// vba (two analyzers, no display family), the emitted vocabulary grew from ten to
// fourteen, and one family claimed a registry id (`sass`) the engine routes to a
// different analyzer than the family's own module.
//
// This generator derives every factual field from the same sources the product
// reads (see script/site-truth/lib.ts) and keeps ONLY the editorial fields typed:
// display name, icon, brand colour, the authored `extracts` line and the
// ecosystem band. The derived fields cannot be typed in; the editorial table
// cannot silently drop or invent a family — the run fails closed against the
// analyzer inventory in both directions.
//
// Regenerate: npx tsx script/site-truth/generate-languages.ts
// Check:      npx tsx script/site-truth/generate-languages.ts --check
// Gate:       npx tsx script/m56/verify-languages-surface.ts
//
// Deterministic: no timestamps, stable sorts, fixed field order. `--check` is a
// byte comparison, so a hand edit to the generated file fails it.

import { readFileSync, writeFileSync } from "node:fs"
import path from "node:path"

import {
  ROOT,
  assertTruthSources,
  dedicatedLanguageCount,
  extensionLabelFor,
  readEngineTruth,
  repoPath,
  type EngineTruth,
} from "./lib.ts"

const OUT_PATH = repoPath("website/src/data/brain-languages.ts")
const CHECK_MODE = process.argv.includes("--check")

function fail(msg: string): never {
  console.error(`generate-languages: FAIL — ${msg}`)
  process.exit(1)
}

/** Editorial inputs. Everything else about a row is derived. */
type FamilyInput = {
  /** Analyzer module token (src/ast/real-<module>-analyzer.ts). The join key. */
  module: string
  name: string
  icon: string
  color: string
  extracts: string
  band: string
}

/** Ecosystem bands, in reading order. Every family names exactly one. */
const BAND_ORDER = ["Application & systems", "Functional & declarative", "Scripting & shell", "Web, data & config"] as const

